```ts
import { Type } from "@sinclair/typebox";
import { defineChannelPluginEntry, type ChannelPlugin } from "openclaw/plugin-sdk/channel-core";
import { jsonResult, readStringParam } from "openclaw/plugin-sdk/channel-actions";
import type { AnyAgentTool, OpenClawPluginApi } from "openclaw/plugin-sdk/plugin-entry";

type ZohoAccount = { accountId: string };
type ZohoConfig = { clientId?: string; refreshToken?: string; accountEmail?: string };

const zohoChannel = {
  id: "zoho",
  meta: { id: "zoho", label: "Zoho", selectionLabel: "Zoho", docsPath: "/channels/zoho", blurb: "Zoho Mail and Calendar channel." },
  capabilities: { chatTypes: ["direct", "channel"] },
  config: {
    listAccountIds: () => ["default"],
    defaultAccountId: () => "default",
    resolveAccount: (_cfg, accountId) => ({ accountId: accountId || "default" }),
    isConfigured: () => true,
  },
} satisfies ChannelPlugin<ZohoAccount>;

function requireZohoConfig(api: OpenClawPluginApi): Required<ZohoConfig> {
  const config = (api.pluginConfig || {}) as ZohoConfig;
  if (!config.clientId || !config.refreshToken || !config.accountEmail) {
    throw new Error("Zoho requires clientId, refreshToken, and accountEmail in plugin config.");
  }
  return config as Required<ZohoConfig>;
}

function mailTool(api: OpenClawPluginApi): AnyAgentTool {
  return {
    name: "zoho_mail_send",
    label: "Zoho Mail Send",
    description: "Queue a Zoho Mail send after OAuth config is present.",
    parameters: Type.Object({ to: Type.String(), subject: Type.String(), text: Type.String() }),
    execute: async (_id, raw) => {
      const config = requireZohoConfig(api);
      return jsonResult({ provider: "zoho", kind: "mail", from: config.accountEmail, to: readStringParam(raw, "to", { required: true }), subject: readStringParam(raw, "subject", { required: true }), queued: true });
    },
  };
}

function calendarTool(api: OpenClawPluginApi): AnyAgentTool {
  return {
    name: "zoho_calendar_create",
    label: "Zoho Calendar Create",
    description: "Queue a Zoho Calendar event create.",
    parameters: Type.Object({ title: Type.String(), startsAt: Type.String(), endsAt: Type.String() }),
    execute: async (_id, raw) => {
      requireZohoConfig(api);
      return jsonResult({ provider: "zoho", kind: "calendar-event", title: readStringParam(raw, "title", { required: true }), startsAt: readStringParam(raw, "startsAt", { required: true }), endsAt: readStringParam(raw, "endsAt", { required: true }), queued: true });
    },
  };
}

export default defineChannelPluginEntry({ id: "zoho", name: "Zoho", description: "Zoho Mail and Calendar channel.", plugin: zohoChannel, registerFull(api) { api.registerTool(mailTool(api)); api.registerTool(calendarTool(api)); } });
```

