1511:     });

1447: async function rehydratePromotionCandidate(
1448:   workspaceDir: string,
1449:   candidate: PromotionCandidate,
1450: ): Promise<PromotionCandidate | null> {
1451:   const sourcePaths = resolveShortTermSourcePathCandidates(workspaceDir, candidate.path);
1452:   for (const sourcePath of sourcePaths) {
1453:     let rawSource: string;
1454:     try {
1455:       rawSource = await fs.readFile(sourcePath, "utf-8");
1456:     } catch (err) {
1457:       if ((err as NodeJS.ErrnoException)?.code === "ENOENT") {
1458:         continue;
1459:       }
1460:       throw err;
1461:     }
1462: 
1463:     const lines = rawSource.split(/\r?\n/);
1464:     const relocated = relocateCandidateRange(lines, candidate);
1465:     if (!relocated) {
1466:       continue;
1467:     }
1468:     return {
1469:       ...candidate,
1470:       startLine: relocated.startLine,
1471:       endLine: relocated.endLine,
1472:       snippet: relocated.snippet,
1473:     };
1474:   }
1475:   return null;
1476: }
